import{_ as t,o as a,c as o,ag as n}from"./chunks/framework.2cFhd8Ux.js";const g=JSON.parse('{"title":"Week 2 — Inside Real Agents","description":"","frontmatter":{"source":"weeks/02-inside-agents/README.md"},"headers":[],"relativePath":"weeks/02-inside-agents/index.md","filePath":"weeks/02-inside-agents/index.md"}'),r={name:"weeks/02-inside-agents/index.md"};function s(i,e,d,h,l,c){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="week-2--inside-real-agents" tabindex="-1">Week 2 — Inside Real Agents <a class="header-anchor" href="#week-2--inside-real-agents" aria-label="Permalink to &quot;Week 2 — Inside Real Agents&quot;">​</a></h1><blockquote><p>A production agent runs the same loop as yours inside a much larger harness, and the way to learn a large codebase, including that harness, is to let an agent map it and then verify every claim the map makes.</p></blockquote><h2 id="this-week-at-a-glance" tabindex="-1">This week at a glance <a class="header-anchor" href="#this-week-at-a-glance" aria-label="Permalink to &quot;This week at a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td><strong>Before the Seminar</strong></td><td>Submit the week 1 assignment; post your reading response; read <a href="./../../project/class-codebase.html">the class codebase</a> and <a href="./../../setup/sandboxes.html">sandboxes</a>. Do the Lab&#39;s <a href="./lab.html#before-the-lab-20-min">before-the-Lab steps</a> early: building takes a while</td></tr><tr><td><strong>Seminar</strong></td><td>🔴 Due-date quiz on the week 1 assignment (7 min) · harness architecture compared with <code>mini-agent</code> · reading a large codebase · debate on the reading · demo · teams announced (<a href="https://boyu-zhang-uoi.github.io/engineering-software-with-ai/slides/week-02.html" target="_blank" rel="noreferrer">slides</a>)</td></tr><tr><td><strong>Lab</strong></td><td>Onboard to the class codebase: build it in a Codespace from its README, run its tests, map its architecture with an agent, verify the claims. <strong>Checkoff:</strong> build and test evidence, the agent&#39;s map saved, at least five claims checked against the code and tagged (<a href="./lab.html#lab--onboard-to-the-class-codebase-75-min">lab</a>)</td></tr><tr><td><strong>Due before next week&#39;s Seminar</strong></td><td>Default 11:59 pm the night before: your individual <a href="./lab.html#assignment--the-onboarding-report">onboarding report</a> · your team&#39;s <code>course/TEAM_CHARTER.md</code>. Week 3&#39;s Seminar opens with a quiz on the report</td></tr><tr><td><strong>AI use this week</strong></td><td>🟢 AI on: exploring and mapping the codebase with an agent; building and running it · 🔴 AI off: the quiz; verifying claims and writing the report&#39;s &quot;verified&quot; and &quot;got wrong&quot; sections; the reading response</td></tr><tr><td><strong>Reading</strong></td><td>Anthropic Engineering, <a href="https://www.anthropic.com/engineering/claude-code-sandboxing" target="_blank" rel="noreferrer">&quot;Beyond permission prompts: making Claude Code more secure and autonomous&quot;</a> (October 2025)</td></tr><tr><td><strong>Reading response</strong></td><td>150–250 words on Canvas, 🔴 AI off, due before the Seminar (<a href="#reading">prompt</a>)</td></tr><tr><td><strong>Team project</strong></td><td>Teams of 3–4 are announced in the Seminar, with a team fork each. Your team writes and signs <code>course/TEAM_CHARTER.md</code> (<a href="./../../templates/TEAM_CHARTER.html">template</a>)</td></tr><tr><td><strong>Graduate track</strong></td><td>CS [5xxx]: the presentation and discussant schedule is posted by the end of the week (<a href="./../../graduate/paper-presentations.html#schedule-rules">rules</a>); week 3 and 4 presenters start now</td></tr><tr><td><strong>Time</strong></td><td>Seminar and Lab 2.5 h · outside about 6 h (CS [5xxx] about 7.5): reading 45 min, setup 20 min, report about 4 h, charter meeting 45 min</td></tr></tbody></table><h2 id="learning-objectives" tabindex="-1">Learning objectives <a class="header-anchor" href="#learning-objectives" aria-label="Permalink to &quot;Learning objectives&quot;">​</a></h2><p>By the end of this week you can:</p><ol><li>Name the parts of a production harness (system prompt assembly, tool schemas, context management, subagents, permission modes, sandboxing) and match each to its counterpart in <code>mini-agent</code>, if it has one.</li><li>Explain why a sandbox needs both filesystem and network isolation, and which one a Codespace lacks.</li><li>Build an unfamiliar codebase from its README and run its tests, recording every step that the README got wrong.</li><li>Map a large codebase with an agent, then verify the map&#39;s claims by reading, running and deliberately breaking code.</li><li>Find the risky areas of a codebase from evidence (history, tests, what the code enforces), not impressions.</li></ol><h2 id="seminar" tabindex="-1">Seminar <a class="header-anchor" href="#seminar" aria-label="Permalink to &quot;Seminar&quot;">​</a></h2><p>The 7-minute quiz on your week 1 work (<a href="./../../assessment/quizzes.html">quizzes</a>); a production harness opened part by part beside <code>mini-agent</code>; a method for reading a codebase too big to hold in your head; a debate on whether approval prompts are a security boundary; a demo that catches an agent&#39;s map being wrong; and the new teams. <a href="https://boyu-zhang-uoi.github.io/engineering-software-with-ai/slides/week-02.html" target="_blank" rel="noreferrer">Slides</a>.</p><h2 id="lab" tabindex="-1">Lab <a class="header-anchor" href="#lab" aria-label="Permalink to &quot;Lab&quot;">​</a></h2><p>Build the codebase your team will work in from its README alone, run its tests, have an agent map it with a citation for every claim, and check the claims yourself. The assignment turns this into your onboarding report, the basis of your team&#39;s M0 proposal. <a href="./lab.html">Lab and assignment</a>.</p><h2 id="reading" tabindex="-1">Reading <a class="header-anchor" href="#reading" aria-label="Permalink to &quot;Reading&quot;">​</a></h2><p>Anthropic Engineering, <a href="https://www.anthropic.com/engineering/claude-code-sandboxing" target="_blank" rel="noreferrer">&quot;Beyond permission prompts: making Claude Code more secure and autonomous&quot;</a> (October 2025), the reading list&#39;s <a href="./../../resources/reading-list.html#week-2--inside-real-agents">core pick</a>.</p><p><strong>Reading response</strong> (150–250 words, 🔴 AI off, on Canvas, before the Seminar; <a href="./../../assessment/rubrics.html#reading-response-5-points">rubric</a>): state the post&#39;s main claim and the 84% figure. What exactly was measured, by whom, against what baseline? This is vendor evidence: what would you need to see to trust it? Your <code>mini-agent</code> has a workspace guard and an approval gate: which of the post&#39;s two kinds of isolation does it have, and for which tools? What will you change in how you run an agent on the class codebase this week? End with one question for the debate.</p><h2 id="key-ideas" tabindex="-1">Key ideas <a class="header-anchor" href="#key-ideas" aria-label="Permalink to &quot;Key ideas&quot;">​</a></h2><p><strong>Same loop, bigger harness.</strong> A production CLI agent still sends the conversation and tool schemas, runs the tool calls and loops. Everything else in the <a href="./../../resources/glossary.html#harness">harness</a> is what makes it usable and safe, and it changes results: on SWE-bench Pro, scaffolds alone shift scores by tens of points (<a href="https://arxiv.org/abs/2509.16941" target="_blank" rel="noreferrer">Deng et al.</a>, Tables 1 and 5).</p><p><strong>Prompts and schemas are assembled.</strong> <code>mini-agent</code> has one fixed <a href="./../../resources/glossary.html#system-prompt">system prompt</a>. Production harnesses typically build theirs at run time from parts: rules, tool guidance, the environment, project files such as <code>AGENTS.md</code>. Tool names, descriptions and parameters are all the model knows about a tool. Find out what the class codebase does by reading its code, not by asking it.</p><p><strong>Context has to be managed.</strong> Harnesses truncate tool output, read files in ranges and <a href="./../../resources/glossary.html#compaction">compact</a> old turns, because quality falls as input grows: all 18 models in Chroma&#39;s tests degraded (<a href="./../../resources/glossary.html#context-rot">context rot</a>). A <a href="./../../resources/glossary.html#subagent">subagent</a> explores with a fresh context and returns a summary of code the parent never saw: treat it as inferred (<a href="./../../resources/agent-patterns.html#subagents">agent patterns</a>).</p><p><strong>Approval prompts are not the boundary.</strong> Injected text has made an agent switch on its own auto-approve setting (<a href="./../../resources/case-studies.html#a4-copilot-edits-its-own-permissions-and-camoleak">case A4</a>), and people stop reading prompts they see too often. The boundary is a sandbox with filesystem <em>and</em> network isolation; a Codespace gives you the first, not the second (<a href="./../../setup/sandboxes.html#what-a-sandbox-does-and-doesnt-protect">sandboxes</a>).</p><p><strong>Read a large codebase outside in.</strong> Build it, run the tests, find the entry points, follow one request end to end, use tests as documentation and history for hotspots. Michigan&#39;s EECS 498, working in Aider&#39;s 20,000 lines, says &quot;Learn, then design, then build&quot; (<a href="https://github.com/eecs498-aase/materials/blob/HEAD/labs/Lab03/slides.md" target="_blank" rel="noreferrer">Lab03</a>). Agents miss project knowledge: of 567 PRs written with one CLI agent, 83.8% were merged, but 45.1% of those needed further changes, mostly bug fixes, docs and project conventions (<a href="https://arxiv.org/abs/2509.14745" target="_blank" rel="noreferrer">Watanabe et al.</a>).</p><h2 id="check-your-understanding" tabindex="-1">Check your understanding <a class="header-anchor" href="#check-your-understanding" aria-label="Permalink to &quot;Check your understanding&quot;">​</a></h2><ol><li>Name three things a production harness adds around the loop that <code>mini-agent</code> doesn&#39;t have, and the problem each solves.</li><li>An agent&#39;s subagent reports that &quot;all permission checks go through <code>checkPermission</code>&quot;. What tag does that claim get, and what two checks would change it?</li><li>Your codespace has your free-tier key as a secret. What can a prompt-injected agent inside it do with that key, and what can&#39;t it reach?</li><li>Why does the onboarding Lab have you build from the README before you ask an agent anything?</li></ol><details><summary>Answers</summary><ol><li>For example: compaction (the window fills), permission modes (fewer, better prompts), an OS-level sandbox (a path check can&#39;t confine a shell), subagents (exploring without flooding the parent). 2. Inferred. Read the function and its callers (<code>git grep -n</code>), and break one check on purpose to see which test fails. 3. Read it with <code>env</code> and send it out, since a Codespace doesn&#39;t restrict outbound traffic; it can&#39;t reach your laptop or other repositories. 4. You need a working build and test command to verify anything the agent claims, and the README&#39;s errors are observed findings.</li></ol></details><h2 id="if-a-tool-is-down" tabindex="-1">If a tool is down <a class="header-anchor" href="#if-a-tool-is-down" aria-label="Permalink to &quot;If a tool is down&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Problem</th><th>What to do</th></tr></thead><tbody><tr><td>The primary CLI agent is rate-limited or down</td><td>The fallback in week 2&#39;s row of <a href="./../../TOOLS.html#tools-by-week">Tool Handout: Tools by week</a>, or Copilot Ask mode, one question at a time. Log the switch</td></tr><tr><td>The class codebase won&#39;t build</td><td><a href="./../../resources/troubleshooting.html#the-class-codebase-wont-build">Troubleshooting</a>; map and verify by reading, and record the blocker exactly</td></tr><tr><td>Out of Codespaces hours</td><td>A dev container on your laptop (<a href="./../../setup/sandboxes.html#dev-containers-on-your-laptop">sandboxes</a>); on campus or the VPN it can use the lab machine with a free harness</td></tr></tbody></table><h2 id="going-further" tabindex="-1">Going further <a class="header-anchor" href="#going-further" aria-label="Permalink to &quot;Going further&quot;">​</a></h2><ul><li>Merrill et al., <a href="https://arxiv.org/abs/2601.11868" target="_blank" rel="noreferrer">&quot;Terminal-Bench&quot;</a>, ICLR 2026: 89 terminal tasks with verification tests; frontier agents score below 65%.</li><li>Murphy-Hill, Butler &amp; Savelieva, <a href="https://arxiv.org/abs/2607.01418" target="_blank" rel="noreferrer">&quot;Adoption and Impact of Command-Line AI Coding Agents&quot;</a>: at Microsoft, adopters merged about 24% more PRs than their counterfactual.</li><li>Liu et al., <a href="https://arxiv.org/abs/2509.22040" target="_blank" rel="noreferrer">&quot;&#39;Your AI, My Shell&#39;&quot;</a>: instructions planted in project files made agentic editors run malicious commands up to 84% of the time. <strong>[Grad seminar]</strong></li><li>More in the <a href="./../../resources/reading-list.html#week-2--inside-real-agents">reading list</a>.</li></ul>',27)])])}const m=t(r,[["render",s]]);export{g as __pageData,m as default};
